//! The tables of the tests of the OpenPGP functions (generated by `port_helpers/gen_pgp_tests.py`):
//! the keys (fixtures of `/tmp/pgpt`, see `port_helpers/gen_pgp_fixtures.sh`), and what Warp 10
//! 3.5.0 answers to the scripts that use them. A key is written `@NAME` in a script, its public
//! ring (or public key) being `@NAME` and its secret ring `@NAMESEC`: ALICE is an RSA 2048 key with
//! a subkey, DSA has an ElGamal subkey, ED, P256, P384, P521, BP and K1 are the curves, EXP expires,
//! NOPASS is unprotected, and V3 is a v3 RSA key. The other series are the armored and the
//! malformed inputs.
//! The expectations are the answers of Warp 10 3.5.0 to the same scripts:
//! the JSON stack (top first) or the error message (in its JDK 11+ form).

use crate::tests::test_stack;
use crate::value::Value;

const ALICE: &str = r"'' B64->";
const ALICESEC: &str = r"'' B64->";
const DSA: &str = r"'' B64->";
const DSASEC: &str = r"'' B64->";
const ED: &str = r"'' B64->";
const EDSEC: &str = r"'' B64->";
const P256: &str = r"'' B64->";
const P256SEC: &str = r"'' B64->";
const P384: &str = r"'' B64->";
const P384SEC: &str = r"'' B64->";
const P521: &str = r"'' B64->";
const P521SEC: &str = r"'' B64->";
const BP: &str = r"'' B64->";
const BPSEC: &str = r"'' B64->";
const K1: &str = r"'' B64->";
const K1SEC: &str = r"'' B64->";
const EXP: &str = r"'' B64->";
const EXPSEC: &str = r"'' B64->";
const NOPASS: &str = r"'' B64->";
const NOPASSSEC: &str = r"'' B64->";
const V3: &str = r"'' B64->";
const V3SEC: &str = r"'' B64->";
const ALICEB64: &str = r"''";
const ARMOR: &str = r"'' B64->";
const BODY: &str = r"'' B64->";
const TWO: &str = r"'' B64->";
const JUNK: &str = r"'AQID' B64->";
const TAG2: &str = r"'wgEA' B64->";
const TRUNC: &str = r"'' B64->";
const HALF: &str = r"'' B64->";
const BADCRC: &str = r"'' B64->";
const NOCOLON: &str = r"'' B64->";
const BADVER: &str = r"'xgIJAA==' B64->";

/// The script of a template, its `@NAME` placeholders replaced by the series above.
fn expand(template: &str) -> String {
    template
        .replace("@NOPASSSEC", NOPASSSEC)
        .replace("@ALICESEC", ALICESEC)
        .replace("@ALICEB64", ALICEB64)
        .replace("@P256SEC", P256SEC)
        .replace("@P384SEC", P384SEC)
        .replace("@P521SEC", P521SEC)
        .replace("@NOCOLON", NOCOLON)
        .replace("@DSASEC", DSASEC)
        .replace("@EXPSEC", EXPSEC)
        .replace("@NOPASS", NOPASS)
        .replace("@BADCRC", BADCRC)
        .replace("@BADVER", BADVER)
        .replace("@ALICE", ALICE)
        .replace("@EDSEC", EDSEC)
        .replace("@BPSEC", BPSEC)
        .replace("@K1SEC", K1SEC)
        .replace("@V3SEC", V3SEC)
        .replace("@ARMOR", ARMOR)
        .replace("@TRUNC", TRUNC)
        .replace("@P256", P256)
        .replace("@P384", P384)
        .replace("@P521", P521)
        .replace("@BODY", BODY)
        .replace("@JUNK", JUNK)
        .replace("@TAG2", TAG2)
        .replace("@HALF", HALF)
        .replace("@DSA", DSA)
        .replace("@EXP", EXP)
        .replace("@TWO", TWO)
        .replace("@ED", ED)
        .replace("@BP", BP)
        .replace("@K1", K1)
        .replace("@V3", V3)
}

/// The stack left by `script`, top first, as the exec endpoint of Warp 10 answers it: the JSON
/// of the stack, as one JSON string in a JSON array. Or the error message.
fn stack_json(script: &str) -> Result<String, String> {
    let mut stack = test_stack();
    stack
        .exec_checked(&format!("{script} DEPTH ->LIST REVERSE ->JSON"))
        .map_err(|err| err.to_string())?;
    match stack.pop().expect("pop should succeed") {
        Value::String(json) => serde_json::to_string(&[json.to_string()]).map_err(|e| e.to_string()),
        other => panic!("not a string: {other:?}"),
    }
}

/// Check every case, reporting all the mismatches at once.
fn check(cases: &[(&str, Result<&str, &str>)]) {
    let mut failures = Vec::new();
    for (template, expected) in cases {
        let script = expand(template);
        match (expected, stack_json(&script)) {
            (Ok(json), Ok(actual)) if actual == *json => {}
            (Err(message), Err(actual)) if actual.contains(message) => {}
            (expected, actual) => failures.push(format!(
                "{template}\n  expected {expected:?}\n  actual   {actual:?}"
            )),
        }
    }
    assert!(failures.is_empty(), "{} failures:\n{}", failures.len(), failures.join("\n"));
}

#[test]
fn pgp_ring() {
    check(&[
        (r"@ALICE PGPRING 0 GET PGPRING ->B64 @ALICE ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@DSA PGPRING 0 GET PGPRING ->B64 @DSA ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@ED PGPRING 0 GET PGPRING ->B64 @ED ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@P256 PGPRING 0 GET PGPRING ->B64 @P256 ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@P384 PGPRING 0 GET PGPRING ->B64 @P384 ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@P521 PGPRING 0 GET PGPRING ->B64 @P521 ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@BP PGPRING 0 GET PGPRING ->B64 @BP ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@K1 PGPRING 0 GET PGPRING ->B64 @K1 ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@EXP PGPRING 0 GET PGPRING ->B64 @EXP ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@NOPASS PGPRING 0 GET PGPRING ->B64 @NOPASS ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@V3 PGPRING 0 GET PGPRING ->B64 @V3 ->B64 ==", Ok(r#"["[false]"]"#)),
        (r"@ALICESEC PGPRING 0 GET PGPRING ->B64 @ALICESEC ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@DSASEC PGPRING 0 GET PGPRING ->B64 @DSASEC ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@EDSEC PGPRING 0 GET PGPRING ->B64 @EDSEC ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@P256SEC PGPRING 0 GET PGPRING ->B64 @P256SEC ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@P384SEC PGPRING 0 GET PGPRING ->B64 @P384SEC ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@P521SEC PGPRING 0 GET PGPRING ->B64 @P521SEC ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@BPSEC PGPRING 0 GET PGPRING ->B64 @BPSEC ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@K1SEC PGPRING 0 GET PGPRING ->B64 @K1SEC ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@EXPSEC PGPRING 0 GET PGPRING ->B64 @EXPSEC ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@NOPASSSEC PGPRING 0 GET PGPRING ->B64 @NOPASSSEC ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@V3SEC PGPRING 0 GET PGPRING ->B64 @V3SEC ->B64 ==", Ok(r#"["[false]"]"#)),
        (r"@ALICE PGPRING 0 GET PGPRING ->B64", Ok(r#"["[\"\"]"]"#)),
        (r"@ARMOR PGPRING 0 GET PGPRING ->B64 @ALICE ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@BODY PGPRING 0 GET PGPRING ->B64 @ALICE ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@ALICEB64 PGPRING 0 GET PGPRING ->B64 @ALICE ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@TWO PGPRING", Ok(r#"["[[null,null]]"]"#)),
        (r"@TWO PGPRING 0 GET PGPRING ->B64 @ALICE ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"@TWO PGPRING 1 GET PGPRING ->B64 @DSA ->B64 ==", Ok(r#"["[true]"]"#)),
        (r"'' PGPRING", Ok(r#"["[[]]"]"#)),
        (r"'abc' PGPRING", Ok(r#"["[[]]"]"#)),
        (r"@JUNK PGPRING", Ok(r#"["[[]]"]"#)),
        (r"@TAG2 PGPRING", Ok(r#"["[[]]"]"#)),
        (r"1 PGPRING", Err(r"PGPRING invalid PGP ring, expected STRING or BYTES.")),
        (r"PGPRING", Err(r"Empty stack.")),
        (r"[ ] PGPRING", Err(r"PGPRING invalid PGP ring, expected STRING or BYTES.")),
        (r"@TRUNC PGPRING", Err(r"PGPRING error decoding PGP key ring. (premature end of stream in PartialInputStream)")),
        (r"@HALF PGPRING", Err(r"PGPRING error decoding PGP key ring. (premature end of stream in PartialInputStream)")),
        (r"@BADCRC PGPRING", Err(r"PGPRING error decoding PGP key ring. (crc check failed in armored message)")),
        (r"@NOCOLON PGPRING", Err(r"PGPRING error decoding PGP key ring. (invalid armor header)")),
        (r"@BADVER PGPRING", Err(r"PGPRING error decoding PGP key ring. (unknown PGP public key algorithm encountered: -1)")),
    ]);
}

