#[test]
fn pgp_objects() {
    check(&[
        (r"@ALICE PGPRING 0 GET TYPEOF", Ok(r#"["[\"KEYRING\"]"]"#)),
        (r"@ALICESEC PGPRING 0 GET TYPEOF", Ok(r#"["[\"KEY\"]"]"#)),
        (r"@ALICE PGPPUBLIC '8C8012054C301346' GET 'key' GET TYPEOF", Ok(r#"["[\"KEY\"]"]"#)),
        (r"@ALICE PGPRING 0 GET ->JSON", Ok(r#"["[\"null\"]"]"#)),
        (r"@ALICESEC PGPRING 0 GET ->JSON", Ok(r#"["[\"null\"]"]"#)),
        (r"@ALICE PGPPUBLIC '8C8012054C301346' GET 'key' GET ->JSON", Ok(r#"["[\"null\"]"]"#)),
        (r"@ALICE PGPRING 0 GET ->PICKLE", Err(r"couldn't pickle object of type class org.bouncycastle.openpgp.PGPPublicKeyRing")),
        (r"@ALICESEC PGPRING 0 GET ->PICKLE", Err(r"couldn't pickle object of type class org.bouncycastle.openpgp.PGPSecretKeyRing")),
        (r"@ALICE PGPPUBLIC '8C8012054C301346' GET 'key' GET ->PICKLE", Err(r"couldn't pickle object of type class org.bouncycastle.openpgp.PGPPublicKey")),
        (r"@ALICE PGPRING 0 GET TOSTRING", Err(r"TOSTRING can only operate on numeric, boolean or string values.")),
        (r"@ALICESEC PGPRING 0 GET TOSTRING", Err(r"TOSTRING can only operate on numeric, boolean or string values.")),
        (r"@ALICE PGPPUBLIC '8C8012054C301346' GET 'key' GET TOSTRING", Err(r"TOSTRING can only operate on numeric, boolean or string values.")),
    ]);
}
